/** Add a formulary drug — POST /api/v1/pharmacy-admin/drugs (who may call: holders of pharmacy.drug.manage). */
export function addDrug(body: DrugIn): Promise<DrugOut> {
  return api<DrugOut>("POST", `/pharmacy-admin/drugs`, body, { idempotent: true });
}

/** Batch intake (boxes × units, invoice cost → unit cost) — POST /api/v1/pharmacy-admin/batches (who may call: holders of pharmacy.stock.receive). */
export function addBatch(body: BatchIn): Promise<DrugBatchOut> {
  return api<DrugBatchOut>("POST", `/pharmacy-admin/batches`, body, { idempotent: true });
}

/** Write off / adjust a batch (expiry, damage) — POST /api/v1/pharmacy-admin/batches/{batch_id}/adjust (who may call: holders of pharmacy.stock.adjust). */
export function adjust(batch_id: number, body: AdjustIn): Promise<StockMovementOut> {
  return api<StockMovementOut>("POST", `/pharmacy-admin/batches/${batch_id}/adjust`, body, { idempotent: true });
}

/** Record a supplier invoice (→ Accounts Payable) — POST /api/v1/pharmacy-admin/vendor-invoices (who may call: holders of pharmacy.vendor_invoice.manage). */
export function addVendorInvoice(body: VendorInvoiceIn): Promise<VendorInvoiceOut> {
  return api<VendorInvoiceOut>("POST", `/pharmacy-admin/vendor-invoices`, body, { idempotent: true });
}

/** Supplier invoices and amounts owed — GET /api/v1/pharmacy-admin/vendor-invoices (who may call: holders of pharmacy.vendor_invoice.manage or finance.ap.view). */
export function listVendorInvoices(query?: { module?: string | null; status?: string | null }): Promise<VendorInvoiceListOut[]> {
  return api<VendorInvoiceListOut[]>("GET", withQuery(`/pharmacy-admin/vendor-invoices`, query), undefined);
}

/** Low-stock widget — GET /api/v1/pharmacy-admin/low-stock (who may call: holders of pharmacy.stock.view). */
export function lowStock(): Promise<LowStockOut[]> {
  return api<LowStockOut[]>("GET", `/pharmacy-admin/low-stock`, undefined);
}

/** Near-expiry widget (money at risk) — GET /api/v1/pharmacy-admin/near-expiry (who may call: holders of pharmacy.stock.view). */
export function nearExpiry(): Promise<NearExpiryOut[]> {
  return api<NearExpiryOut[]>("GET", `/pharmacy-admin/near-expiry`, undefined);
}

/** Gross revenue − COGS = net profit (live) — GET /api/v1/pharmacy-admin/profit-dashboard (who may call: holders of pharmacy.dashboard.view). */
export function profit(query?: { date_from?: string | null; date_to?: string | null }): Promise<ProfitDashboardOut> {
  return api<ProfitDashboardOut>("GET", withQuery(`/pharmacy-admin/profit-dashboard`, query), undefined);
}

/** Vendors — GET /api/v1/finance/vendors (who may call: any logged-in user). */
export function vendors(query?: { vendor_type?: "PharmacySupplier" | "ReagentSupplier" | "EquipmentSupplier" | "UtilityProvider" | "Contractor" | "Other" | null }): Promise<VendorOut[]> {
  return api<VendorOut[]>("GET", withQuery(`/finance/vendors`, query), undefined);
}

/** Return units of a batch to its supplier — POST /api/v1/pharmacy-admin/batches/{batch_id}/supplier-returns (who may call: holders of pharmacy.supplier_return.record). */
export function recordReturn(batch_id: number, body: SupplierReturnIn): Promise<SupplierReturnOut> {
  return api<SupplierReturnOut>("POST", `/pharmacy-admin/batches/${batch_id}/supplier-returns`, body, { idempotent: true });
}

/** Returns to suppliers, newest first — GET /api/v1/pharmacy-admin/supplier-returns (who may call: holders of pharmacy.supplier_return.record or finance.supplier_credit.confirm or finance.ap.view). */
export function listReturnsPharmacyAdminSupplier(query?: { status?: "Returned" | "Credited" | "Refused" | null; vendor_id?: number | null; limit?: number }): Promise<SupplierReturnOut[]> {
  return api<SupplierReturnOut[]>("GET", withQuery(`/pharmacy-admin/supplier-returns`, query), undefined);
}

/** One return to a supplier — GET /api/v1/pharmacy-admin/supplier-returns/{return_id} (who may call: holders of pharmacy.supplier_return.record or finance.supplier_credit.confirm or finance.ap.view). */
export function getReturn(return_id: number): Promise<SupplierReturnOut> {
  return api<SupplierReturnOut>("GET", `/pharmacy-admin/supplier-returns/${return_id}`, undefined);
}

/** The return note that goes with the goods (PDF) — GET /api/v1/pharmacy-admin/supplier-returns/{return_id}/pdf (who may call: holders of pharmacy.supplier_return.record or finance.supplier_credit.confirm). */
export function returnNote(return_id: number): Promise<unknown> {
  return api<unknown>("GET", `/pharmacy-admin/supplier-returns/${return_id}/pdf`, undefined);
}

/** The recall register — GET /api/v1/drug-recalls (who may call: holders of pharmacy.recall.view). */
export function listRecalls(query?: { status?: "Open" | "Closed" | "Cancelled" | null; drug_id?: number | null }): Promise<RecallOut[]> {
  return api<RecallOut[]>("GET", withQuery(`/drug-recalls`, query), undefined);
}

/** Formulary search with live stock colour — GET /api/v1/drugs/search (who may call: holders of pharmacy.formulary.view). */
export function searchDrugs(query?: { q?: string; limit?: number }): Promise<DrugStockOut[]> {
  return api<DrugStockOut[]>("GET", withQuery(`/drugs/search`, query), undefined);
}
